from pathlib import Path
from openpyxl import load_workbook

FILE_PATH = Path("./data/order_summary.xlsx")
ORDER_ID = "ORD-6C71B1"
EXPECTED_STATUS = "cancelled"
NEW_STATUS = "confirmed"

if not FILE_PATH.is_file():
    raise FileNotFoundError(f"Workbook not found: {FILE_PATH.resolve()}")

workbook = load_workbook(FILE_PATH)
matches = []

for sheet in workbook.worksheets:
    # Search each row for recognized Order ID and Status headers.
    for header_row in range(1, min(sheet.max_row, 20) + 1):
        headers = {
            str(cell.value).strip().lower().replace("_", " "): cell.column
            for cell in sheet[header_row]
            if cell.value is not None
        }

        order_column = next(
            (
                headers[name]
                for name in ("order id", "order", "id")
                if name in headers
            ),
            None,
        )
        status_column = headers.get("status")

        if order_column is None or status_column is None:
            continue

        for row_number in range(header_row + 1, sheet.max_row + 1):
            value = sheet.cell(row_number, order_column).value
            if str(value).strip() != ORDER_ID:
                continue

            status_cell = sheet.cell(row_number, status_column)
            current_status = str(status_cell.value).strip().lower()

            if current_status != EXPECTED_STATUS:
                raise ValueError(
                    f"{ORDER_ID} was found in sheet {sheet.title!r}, "
                    f"but its status is {status_cell.value!r}, not "
                    f"{EXPECTED_STATUS!r}. No file was saved."
                )

            status_cell.value = NEW_STATUS
            matches.append(
                f"{sheet.title}!{status_cell.coordinate}"
            )

        # Stop looking for other header rows on this sheet.
        break

if not matches:
    raise ValueError(
        f"{ORDER_ID} was not found with a recognizable Order ID/Status header. "
        "No file was saved."
    )

if len(matches) > 1:
    raise ValueError(
        f"Found multiple matching records ({', '.join(matches)}). "
        "No file was saved; review the workbook manually."
    )

workbook.save(FILE_PATH)
print(
    f"Updated {ORDER_ID} from {EXPECTED_STATUS!r} to {NEW_STATUS!r} "
    f"at {matches[0]} in {FILE_PATH}."
)
